From d090f86dcb7f1888fffaef171561c7d599909ca0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:15:31 +0100
Subject: [PATCH] plasma-apply-wallpaperimage: keep the dynamic wallpaper mode

The tool wrote the bare package path as the Image, dropping the #light,
#dark or #day-night fragment that the "Switch dynamic wallpapers" setting
relies on. For packages with dark images it now appends the fragment.

BUG: 511377
---
 wallpapers/image/plasma-apply-wallpaperimage.cpp | 13 +++++++++++--
 1 file changed, 11 insertions(+), 2 deletions(-)

diff --git a/wallpapers/image/plasma-apply-wallpaperimage.cpp b/wallpapers/image/plasma-apply-wallpaperimage.cpp
index be5ada1a6e..8ae057d491 100644
--- a/wallpapers/image/plasma-apply-wallpaperimage.cpp
+++ b/wallpapers/image/plasma-apply-wallpaperimage.cpp
@@ -13,6 +13,7 @@
 #include <QDBusConnection>
 #include <QDBusMessage>
 #include <QDebug>
+#include <QDir>
 #include <QFileInfo>

 int main(int argc, char **argv)
@@ -51,6 +52,7 @@ int main(int argc, char **argv)
         QFileInfo wallpaperInfo{wallpaperFile};
         bool isWallpaper{false};
         bool isKPackage{false};
+        bool hasDarkVariant{false};
         if (wallpaperFile.contains(u"\'")) {
             // If this happens, we might very well assume that there is some kind of funny business going on
             // even if technically it could just be a possessive. But, security first, so...
@@ -74,6 +76,7 @@ int main(int argc, char **argv)
                         // Similarly to above, we could read all the information out of the kpackage, but
                         // that also is not hugely important, so we just deduce that this reasonably should
                         // be an installed kpackage
+                        hasDarkVariant = !QDir(QStringLiteral("%1/contents/images_dark").arg(wallpaperFile)).isEmpty(QDir::Files | QDir::NoDotAndDotDot);
                     }
                 }
             }
@@ -84,8 +87,14 @@ int main(int argc, char **argv)
             out << "for (var key in desktops()) {" //
                 << "var d = desktops()[key];" //
                 << "d.wallpaperPlugin = 'org.kde.image';" //
-                << "d.currentConfigGroup = ['Wallpaper', 'org.kde.image', 'General'];" //
-                << u"d.writeConfig('Image', 'file://" + wallpaperFile + u"');";
+                << "d.currentConfigGroup = ['Wallpaper', 'org.kde.image', 'General'];";
+            if (hasDarkVariant) {
+                // Keep the "Switch dynamic wallpapers" choice, see DynamicMode::Mode
+                out << "var fragment = ['', '#day-night', '#dark', '#light'][d.readConfig('DynamicMode', 0)] || '';" //
+                    << u"d.writeConfig('Image', 'file://" + wallpaperFile + u"' + fragment);";
+            } else {
+                out << u"d.writeConfig('Image', 'file://" + wallpaperFile + u"');";
+            }

             // Add fill mode to the script if provided
             if (parser.isSet(fillModeOption)) {
-- 
